def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me, op = history[-1]

    opp_d = 0
    opp_c = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
        else:
            opp_c += 1

    recent5 = history[-5:]
    recent10 = history[-10:]

    rec5_d = 0
    rec10_d = 0
    unprov_recent5 = 0

    for m, o in recent5:
        if o == 'D':
            rec5_d += 1
        if m == 'C' and o == 'D':
            unprov_recent5 += 1

    for m, o in recent10:
        if o == 'D':
            rec10_d += 1

    chronic = False
    if opp_c == 0:
        chronic = True
    elif n >= 6 and opp_d * 5 > n * 3:
        chronic = True
    elif unprov_recent5 >= 3:
        chronic = True
    elif rec5_d >= 4 and opp_d >= opp_c:
        chronic = True

    if chronic:
        return 'D'

    if op == 'D':
        if me == 'C':
            if n >= 2 and history[-2][0] == 'D' and rec5_d <= 2:
                return 'C'
            if opp_c >= 3 * opp_d and opp_d <= 3:
                if rng.random() < 0.15:
                    return 'C'
            return 'D'
        else:
            if rec10_d >= 6 and opp_d >= opp_c:
                return 'D'
            return 'C'
    else:
        if n == 98 and rec10_d == 0 and opp_c == n:
            if my_d == 0:
                if rng.random() < 0.3:
                    return 'D'
            else:
                return 'D'
        return 'C'
